def clear_flag_for_non_internal_users(apps, schema_editor):
    UserProfile = apps.get_model("core", "UserProfile")
    Permission = apps.get_model("auth", "Permission")

    perm = Permission.objects.filter(content_type__app_label="core", codename="access_archie").first()
    internal = Q(user__is_superuser=True) | Q(is_philips=True) | Q(is_functional_account=True)
    if perm is not None:
        internal |= Q(user__user_permissions=perm) | Q(user__groups__permissions=perm)
    internal_ids = UserProfile.objects.filter(internal).values("pk")

    to_clear = UserProfile.objects.filter(is_servicenow_technician=True).exclude(pk__in=internal_ids)
    usernames = sorted(to_clear.values_list("user__username", flat=True))
    if usernames:
        print(f"\n  B-22: tolto il flag Tecnico ServiceNow a {len(usernames)} utenti: {', '.join(usernames)}")
    UserProfile.objects.filter(pk__in=list(to_clear.values_list("pk", flat=True))).update(
        is_servicenow_technician=False
    )


